#include <iostream>
#include <vector>
using namespace std;

struct MinHeap {
    vector<int> heap;
    MinHeap(int capacity) { heap.reserve(capacity); }
    void insert(int val) {
        heap.push_back(val);
        int i = (int)heap.size() - 1;
        while (i > 0 && heap[(i - 1) / 2] > heap[i]) {
            int tmp = heap[i];
            heap[i] = heap[(i - 1) / 2];
            heap[(i - 1) / 2] = tmp;
            i = (i - 1) / 2;
        }
    }
    int extractMin() {
        int mn = heap[0];
        heap[0] = heap.back();
        heap.pop_back();
        siftDown(0);
        return mn;
    }
    void siftDown(int i) {
        int n = (int)heap.size();
        int smallest = i, l = 2 * i + 1, r = 2 * i + 2;
        if (l < n && heap[l] < heap[smallest]) smallest = l;
        if (r < n && heap[r] < heap[smallest]) smallest = r;
        if (smallest != i) {
            int tmp = heap[i];
            heap[i] = heap[smallest];
            heap[smallest] = tmp;
            siftDown(smallest);
        }
    }
};

